34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
46	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final TelephoneNormalizer telephoneNormalizer;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 TelephoneNormalizer telephoneNormalizer,
82	                                 AddressNormalizer addressNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.telephoneNormalizer = telephoneNormalizer;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
120	        rejectBlankOwnerFields(ownerFieldsDto);
121	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
122	        if (!sharesHousehold) {
123	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
124	        }
125	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
126	        rejectDuplicateTelephone(normalizedTelephone);
127	        ownerFieldsDto.setTelephone(normalizedTelephone);
128	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
135	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
136	        if (sharesHousehold) {
137	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
138	        }
139	        this.clinicService.saveOwner(owner);
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        headers.setLocation(UriComponentsBuilder.newInstance()
142	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
143	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
149	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
150	        if (currentOwner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        currentOwner.setAddress(ownerFieldsDto.getAddress());
154	        currentOwner.setCity(ownerFieldsDto.getCity());
155	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
156	        currentOwner.setLastName(ownerFieldsDto.getLastName());
157	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
158	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
159	        this.clinicService.saveOwner(currentOwner);
160	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Transactional
165	    @Override
166	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        this.clinicService.deleteOwner(owner);
172	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        HttpHeaders headers = new HttpHeaders();
183	        Pet pet = petMapper.toPet(petFieldsDto);
184	        owner.setId(ownerId);
185	        pet.setOwner(owner);
186	        pet.getType().setName(null);
187	        this.clinicService.savePet(pet);
188	        PetDto petDto = petMapper.toPetDto(pet);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
190	            .buildAndExpand(pet.getId()).toUri());
191	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner != null) {
199	            Pet currentPet = this.clinicService.findPetById(petId);
200	            if (currentPet != null) {
201	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
202	                currentPet.setName(petFieldsDto.getName());
203	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
204	                this.clinicService.savePet(currentPet);
205	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
214	        HttpHeaders headers = new HttpHeaders();
215	        Visit visit = visitMapper.toVisit(visitFieldsDto);
216	        Pet pet = new Pet();
217	        pet.setId(petId);
218	        visit.setPet(pet);
219	        this.clinicService.saveVisit(visit);
220	        VisitDto visitDto = visitMapper.toVisitDto(visit);
221	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
222	            .buildAndExpand(visit.getId()).toUri());
223	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
224	    }
225	
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
230	        Owner owner = this.clinicService.findOwnerById(ownerId);
231	        if (owner != null) {
232	            Pet pet = owner.getPet(petId);
233	            if (pet != null) {
234	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    /**
241	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
242	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
243	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
244	     * blank (e.g. {@code "   "}). The offending field names are reported through an
245	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
246	     * as a 400 response carrying an {@code errors} array of field names.
247	     *
248	     * @param ownerFieldsDto the submitted owner fields
249	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
250	     */
251	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
252	        List<String> blankFields = new ArrayList<>();
253	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
254	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
255	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
256	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
257	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
258	        if (!blankFields.isEmpty()) {
259	            throw new InvalidOwnerFieldsException(blankFields);
260	        }
261	    }
262	
263	    private void addIfBlank(List<String> blankFields, String field, String value) {
264	        if (value != null && value.isBlank()) {
265	            blankFields.add(field);
266	        }
267	    }
268	
269	    /**
270	     * Normalizes an owner's optional email address. When present it is stored and returned
271	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
272	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
273	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
274	     * method runs.
275	     *
276	     * @param email the raw email value from the request, or {@code null} when omitted
277	     * @return the lower-cased email, or {@code null} when none was supplied
278	     */
279	    private String normalizeEmail(String email) {
280	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
281	    }
282	
283	    /**
284	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
285	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
286	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
287	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
288	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
289	     *
290	     * @param city the city of the owner being created
291	     * @param lastName the last name of the owner being created
292	     * @return the formatted customer code
293	     */
294	    private String nextCustomerCode(String city, String lastName) {
295	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
296	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
297	        long sequence = this.clinicService.findAllOwners().stream()
298	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
299	            .count() + 1L;
300	        return String.format("%s-%s-%04d", city3, last3, sequence);
301	    }
302	
303	    /**
304	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
305	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
306	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
307	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
308	     * new owner and surfaced as the read-only {@code namesakeCount} field.
309	     *
310	     * @param firstName the first name of the owner being created
311	     * @param lastName the last name of the owner being created
312	     * @return the number of existing owners with the same first and last name (case-insensitive)
313	     */
314	    private int namesakeCount(String firstName, String lastName) {
315	        return (int) this.clinicService.findAllOwners().stream()
316	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
317	                && equalsIgnoreCase(owner.getLastName(), lastName))
318	            .count();
319	    }
320	
321	    private boolean equalsIgnoreCase(String a, String b) {
322	        return a == null ? b == null : a.equalsIgnoreCase(b);
323	    }
324	
325	    /**
326	     * Rejects a create request whose normalized telephone is already used by any existing owner.
327	     * Existing owners' telephones are reduced to the same canonical form (via
328	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
329	     * only in formatting still collide. A collision is reported through a
330	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
331	     * as a 409 Conflict response.
332	     *
333	     * @param normalizedTelephone the canonical telephone of the owner being created
334	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
335	     */
336	    private void rejectDuplicateTelephone(String normalizedTelephone) {
337	        boolean duplicate = existingOwnerMatches(
338	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
339	            normalizedTelephone);
340	        if (duplicate) {
341	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
342	        }
343	    }
344	
345	    /**
346	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
347	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
348	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
349	     * and the owner being created to the same canonical key and reject a match.
350	     *
351	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
352	     * @param key the canonical key of the owner being created
353	     * @return {@code true} if some existing owner shares the key
354	     */
355	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
356	        return this.clinicService.findAllOwners().stream()
357	            .map(keyExtractor)
358	            .filter(Objects::nonNull)
359	            .anyMatch(key::equals);
360	    }
361	
362	    /**
363	     * Rejects a create request that shares a household with an existing owner: another owner already
364	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
365	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
366	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
367	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
368	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
369	     * check when the request opts in via {@code sharesHousehold}.
370	     *
371	     * @param lastName the last name of the owner being created
372	     * @param address the address of the owner being created
373	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
374	     */
375	    private void rejectDuplicateHousehold(String lastName, String address) {
376	        String canonicalLastName = canonicalizeHousehold(lastName);
377	        String canonicalAddress = canonicalizeHousehold(address);
378	        if (canonicalLastName == null || canonicalAddress == null) {
379	            return;
380	        }
381	        boolean duplicate = this.clinicService.findAllOwners().stream()
382	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
383	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
384	        if (duplicate) {
385	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
386	        }
387	    }
388	
389	    /**
390	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
391	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
392	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
393	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
394	     *
395	     * @param value the raw field value, or {@code null}
396	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
397	     */
398	    private String canonicalizeHousehold(String value) {
399	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
400	    }
401	
402	    /**
403	     * Derives the stable, shared {@code householdId} for an owner joining a household via
404	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
405	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
406	     * owner with the same last name at the same address - regardless of casing or spacing - is
407	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
408	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
409	     *
410	     * @param lastName the last name of the owner being created
411	     * @param address the address of the owner being created
412	     * @return the shared household identifier
413	     */
414	    private String householdId(String lastName, String address) {
415	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
416	        try {
417	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
418	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
419	            StringBuilder sb = new StringBuilder(digest.length * 2);
420	            for (byte b : digest) {
421	                sb.append(String.format("%02X", b));
422	            }
423	            return sb.substring(0, 16);
424	        } catch (java.security.NoSuchAlgorithmException e) {
425	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
426	        }
427	    }
428	}
